from collections import defaultdict
from datetime import date, timedelta


class LeaveTracker:
    def __init__(self, days_per_year: int = 26, holidays: list[date] | None = None) -> None:
        self.days_per_year = days_per_year
        self.holidays = set(holidays) if holidays is not None else set()
        # employee -> year -> set of dates already taken
        self.used_days: dict[str, dict[int, set[date]]] = defaultdict(lambda: defaultdict(set))

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        """Request leave from start to end (inclusive); returns the number of leave days used."""
        if end < start:
            raise ValueError("End date cannot be before start date.")

        if (start - today).days < 3:
            raise ValueError("Request must be made at least 3 days before start date.")

        # Determine leave days by year and check for weekend/holiday
        days_by_year: dict[int, list[date]] = defaultdict(list)
        curr = start
        one_day = timedelta(days=1)
        while curr <= end:
            # Monday is 0, Sunday is 6; weekends are 5 and 6
            if curr.weekday() < 5 and curr not in self.holidays:
                days_by_year[curr.year].append(curr)
            curr += one_day

        # Check if any day is already booked or if total exceeds remaining for that year
        for year, dates in days_by_year.items():
            already_booked = self.used_days[employee][year]
            new_dates = [d for d in dates if d not in already_booked]
            remaining_days = self.remaining(employee, year)
            if len(new_dates) > remaining_days:
                raise ValueError(
                    f"Not enough leave days remaining for year {year}. "
                    f"Required: {len(new_dates)}, Available: {remaining_days}"
                )

        # Commit the days
        total_days_used = 0
        for year, dates in days_by_year.items():
            for d in dates:
                if d not in self.used_days[employee][year]:
                    self.used_days[employee][year].add(d)
                    total_days_used += 1

        return total_days_used

    def remaining(self, employee: str, year: int) -> int:
        used_count = len(self.used_days[employee][year])
        return max(0, self.days_per_year - used_count)
